def table(headers,rows):
 return '<div class="tablewrap"><table><thead><tr>'+''.join('<th>'+E(str(x))+'</th>' for x in headers)+'</tr></thead><tbody>'+''.join('<tr>'+''.join('<td>'+E(str(x))+'</td>' for x in row)+'</tr>' for row in rows)+'</tbody></table></div>'
def paras(text):
 return ''.join('<p>'+x.strip()+'</p>' for x in text.strip().split('\n\n') if x.strip())
def sec(group,id,title,lead,text,refs=(),extra=''):
 sections.append(dict(group=group,id=id,title=title,lead=lead,body=paras(text)+extra,refs=refs))
def callout(title,text): return '<aside class="insight"><b>'+title+'</b><p>'+text+'</p></aside>'
def flow(items,caption='개념도 · 크기는 금액을 뜻하지 않음'):
 return '<figure><div class="flow">'+''.join('<div><b>'+x[0]+'</b><span>'+x[1]+'</span></div>' for x in items)+'</div><figcaption>'+caption+'</figcaption></figure>'
def linechart(title,years,series,unit):
 vals=[v for _,arr,_ in series for v in arr if v is not None]; ymax=max(vals)*1.13; ymin=min(0,min(vals)); W,H=900,300; x=lambda i:65+i*(W-95)/max(1,len(years)-1); y=lambda v:240-(v-ymin)/(ymax-ymin)*205
 s='<figure class="chart"><div class="charttitle">'+title+' <small>'+unit+'</small></div><svg viewBox="0 0 900 300" role="img" aria-label="'+E(title)+'">'
 for i in range(5):
  v=ymin+(ymax-ymin)*i/4; yy=y(v); s+=f'<path d="M60 {yy}H880" stroke="#20374b"/><text x="50" y="{yy+5}" text-anchor="end">{v:,.1f}</text>'
 for i,yr in enumerate(years): s+=f'<text x="{x(i)}" y="268" text-anchor="middle">{yr}</text>'
 for name,arr,c in series:
  pts=' '.join(f'{x(i):.1f},{y(v):.1f}' for i,v in enumerate(arr) if v is not None);s+=f'<polyline points="{pts}" fill="none" stroke="{c}" stroke-width="3"/>'
  for i,v in enumerate(arr):
   if v is not None:s+=f'<circle cx="{x(i)}" cy="{y(v)}" r="4" fill="{c}"><title>{E(name)} {years[i]}: {v:,}</title></circle>'
 s+='</svg><figcaption>'+''.join(f'<span style="color:{c}">● {E(n)}　</span>' for n,_,c in series)+'</figcaption></figure>';return s

sec('01 리니어의 역사','linear-model','고성능 아날로그가 만든 현금의 구조','작은 시장에서도 높은 수익성을 유지할 수 있었던 사업 모델임.', '''리니어 테크놀로지(Linear Technology)는 전력관리와 정밀 신호처리용 아날로그 반도체에 강점이 있던 기업임. 디지털 칩이 0과 1을 계산한다면 아날로그 칩은 전압·온도·소리처럼 연속적인 물리 신호를 다루거나 전기를 알맞게 공급하는 역할을 함. 산업기기·통신장비·자동차 등에 들어가며, 고객 제품에 한번 채택되면 설계를 쉽게 바꾸기 어려운 특성이 있음.

제품의 수명이 길고 고객이 요구하는 정확도·신뢰성이 중요하므로, 최신 미세공정을 먼저 도입하는 것만으로 승부가 결정되지 않았음. 이미 투자한 설비와 축적한 설계 경험을 오래 활용할 수 있었음. 이를 통해 높은 마진과 낮은 추가 투자 부담이 공존했으며, 회계상 이익이 현금으로 전환되는 비율도 높은 편이었음.

다만 ‘아날로그는 언제나 설비가 저렴함’으로 일반화하면 안 됨. 2003년 케이스의 공장 투자비 비교는 당시 상황을 설명하는 예시임. 이후 대형 아날로그 기업의 300mm 팹 투자, 공급망 재편, 공정 내재화는 훨씬 큰 투자 규모를 요구함. 사업 모델의 경제성과 특정 시기의 투자비를 구분할 필요 있음.''',('CASE','analog_technology','linear_10k_2016'),flow([('현실 신호','온도·빛·소리·전압'),('아날로그 칩','변환·증폭·전력관리'),('고객 설계','검증과 장기 채택'),('현금 창출','긴 제품 수명·재투자 효율')]))

sec('01 리니어의 역사','linear-2003','2003년: 투자 기회보다 현금이 많았음','배당·자사주·현금 보유를 비교하는 출발점임.', '''IT 불황 이후에도 리니어에는 현금과 단기투자자산이 쌓였음. 2003년 3월 말 약 15억 달러 규모였으며, FY2002 매출 약 5.1억 달러에 비해 상당히 큰 금액이었음. 당장 계획한 대규모 인수가 없고 설비투자 부담도 제한적이면, 현금의 추가 보유가 창출하는 가치와 주주가 다른 곳에 투자할 때 얻을 가치를 비교해야 함.

배당은 반복 지급의 약속에 가까움. 주주는 배당을 지속 가능한 이익에 대한 신호로 받아들이므로, 경영진은 한번 올린 배당을 줄일 때의 비용을 고려하게 됨. 자사주 매입은 집행 규모를 조정하기 쉽지만 매입 가격이 중요함. 같은 금액을 써도 주가가 내재가치보다 높으면 남은 주주의 가치에 불리할 수 있음.

현금 보유에는 불황 대응, 연구개발의 연속성, 인수 기회 확보라는 옵션 가치가 있음. 반면 지나치게 많은 현금은 낮은 수익률, 경영진의 비효율적 투자, 자본규율 약화로 이어질 수 있음. 따라서 배당이 많다고 성숙한 기업이고 적다고 성장기업이라는 단순 분류보다, 투자 기회의 질과 내부자금의 필요성을 먼저 봐야 함.''',('CASE','linear_q3fy03'),callout('핵심 비교','투자안의 기대수익률이 자본비용을 넘는지 확인한 뒤, 남는 현금을 얼마나 보유하고 환원할지 결정하는 순서가 적절함.'))

ls=D['linear']['series']; ly=[str(x['fy'])[2:] for x in ls]
sec('01 리니어의 역사','linear-trend','2003–2016년: 배당 증가와 매출 정체가 공존함','성숙기의 수익성과 성장의 한계를 따로 읽어야 함.', '''FY2003 매출은 6.066억 달러, FY2016 매출은 14.239억 달러였음. 긴 기간 전체로는 성장했으나 FY2011의 14.840억 달러 이후에는 13억~15억 달러 수준에서 움직였음. FY2011–2016 매출 연평균 성장률은 약 −0.8%임. 호황 정점 한 해를 기준으로 잡은 값이므로, 2012년 저점 이후 회복과 함께 읽어야 함.

같은 기간 연간 주당배당은 FY2003 0.21달러에서 FY2016 1.24달러로 증가했음. 주당배당과 매출은 단위도 경제적 의미도 다름. 배당 증가는 이익의 배분 비율, 주식 수 감소, 현금 축적분의 사용으로도 가능함. 매출이 정체되어도 배당을 늘릴 수 있으므로, 배당성장률을 사업성장률의 대용으로 쓰면 안 됨.

FY2016 영업이익률은 44.5%였음. 높은 수익성을 유지했다는 점은 분명하지만, 좋은 기존 사업과 새 성장동력을 확보하는 능력은 서로 다른 질문임. 매각은 파산이나 제품 소멸이 아니라, 독립적인 상장기업의 종료였음. 리니어의 기술과 제품은 ADI의 포트폴리오 안에서 계속 활용됨.''',('linear_10k_2007','linear_10k_2016'),linechart('리니어 매출: 2011년 이후 뚜렷해진 정체',ly,[('매출',[x['revenue'] for x in ls],'#37ccff')],'백만 달러 · FY2003–2016')+linechart('주당배당: 매년 높아진 환원',ly,[('연간 DPS',[x['dps'] for x in ls],'#39e2b0')],'달러/주 · 연간 합계'))

sec('01 리니어의 역사','linear-capital','2007년: 차입을 이용한 자사주 매입','현금 보유에서 자본구조 재편으로 이동한 결정임.', '''2007년 리니어는 30억 달러 규모의 가속 자사주 매입(ASR)을 실행했음. 재원은 보유 현금 약 13억 달러와 전환사채 약 17억 달러였음. 이 거래는 단순히 남는 현금을 배당으로 지급한 것이 아니라, 부채와 자기자본의 비중을 바꾼 자본구조 재편으로 이해하는 편이 적절함.

전환사채는 채권자에게 주식으로 전환할 권리를 제공하므로 일반채권보다 낮은 쿠폰으로 발행될 수 있음. 낮은 이자율은 무료 자금이라는 뜻이 아님. 미래 희석 가능성, 조기 상환 조건, 주가와 신용도의 변화가 경제적 비용에 포함됨. 주식 수가 줄어 주당이익이 오르는 효과와 기업 전체의 영업가치가 커지는 효과도 구분해야 함.

리니어는 이후 영업현금으로 부채를 줄였으며 2014년 전환사채를 모두 상환해 무차입으로 돌아왔음. 인수 직전의 리니어를 ‘빚 때문에 팔린 회사’라고 설명하기 어려운 이유임. 주주환원 자체가 성장 정체의 원인이었다고 단정할 근거도 부족함. 포기한 투자안의 기대수익이 높았는지, 실제 투자할 만한 기회가 있었는지를 함께 확인해야 함.''',('linear_10k_2007','linear_10k_2016'),table(['선택','긍정적 효과','확인할 비용'],[['배당','현금 배분의 예측 가능성','삭감 시 신호 효과·지급 지속 부담'],['자사주 매입','집행 유연성·주당 지분 증가','고평가 매입·재무 여력 감소'],['차입 환원','자본구조 조정·이자 세금효과','차환 위험·이자 부담·전환 희석'],['현금 보유','불황 대응·투자 선택권','기회비용·비효율적 투자 가능성']]))

sec('01 리니어의 역사','linear-peers','경쟁사와의 차이는 규모와 포트폴리오였음','매출성장률만으로 전략의 우열을 판정하면 오해가 생김.', '''TI·ADI·Maxim·Linear는 모두 아날로그 사업을 영위했으나 제품 구성과 고객군이 같지 않았음. 리니어는 정밀도와 성능을 중시하는 제품, 긴 제품 수명, 높은 마진에 집중했음. TI는 넓은 제품군과 제조 규모, ADI는 신호처리 기술 및 산업·자동차 고객, Maxim은 전력관리와 혼합신호 제품 등 각기 다른 강점을 갖고 있었음.

TI의 National Semiconductor 인수, ADI의 Hittite 인수와 이후 Linear·Maxim 인수는 비교를 복잡하게 만듦. 인수로 추가된 매출을 포함한 연결 매출 성장률은 기존 제품의 유기적 성장률과 다름. 회계연도 종료일도 회사별로 다르므로 같은 연도 표기를 그대로 같은 경기 국면으로 보기는 어려움.

리니어가 상대적으로 좁은 고수익 영역을 지켰다는 해석은 가능함. 그러나 모든 경쟁사가 빠르게 성장한 반면 리니어만 실패했다는 서사는 적절하지 않음. 아날로그 산업 자체의 경기 둔화와 고객 재고 조정도 있었음. 핵심 비교는 성장률·영업이익률·R&D 비율·CAPEX 부담·인수 효과를 함께 보는 것임.''',('linear_10k_2016','NATIONAL','MAXIM'),table(['회사','전략적 특징','비교할 때의 유의점'],[['Linear','고성능 아날로그·높은 마진','성장 정체와 수익성 저하를 구분'],['Texas Instruments','광범위한 아날로그·자체 제조 규모','제품 믹스·인수·공장 투자 영향'],['Analog Devices','신호처리·산업 및 자동차·M&A','Hittite·Linear·Maxim 연결 효과'],['Maxim Integrated','혼합신호·전력관리','소비자기기 노출·사업 매각 영향']]))

sec('01 리니어의 역사','linear-sale','2015–2017년: 독자 가치와 인수 프리미엄의 비교','이사회는 첫 제안을 거절한 뒤 조건을 높여 거래했음.', '''합병 위임장에 따르면 ADI는 2015년 리니어에 접근했음. 2015년 8월의 비공식 제안은 주당 약 51.50달러 수준이었으며, 리니어 이사회는 독자 경영의 가치에 비해 부족하다고 판단했음. 이후 협상과 다른 잠재 매수자에 대한 검토가 이어졌고, 2016년 7월 거래가 발표되었음.

최종 조건은 리니어 1주당 현금 46달러와 ADI 주식 0.2321주였음. 발표 당시 약 60달러의 주당 가치와 약 148억 달러의 거래 가치로 설명되었음. 현금 부분은 확정되지만 ADI 주식 부분은 시장가격에 따라 변하므로, 거래 전체가 무위험 확정 프리미엄이라고 말할 수는 없음. 인수 완료 시 회계상 취득대가도 발표 당시 거래가치와 달라질 수 있음.

2017년 3월 10일 인수가 완료되었음. 독립 존속 시의 장기 가치와 인수 프리미엄의 비교에서는 할인율, 매출 성장 가정, 마진 유지, 미래 투자 기회가 핵심임. 매수자가 얻는 제품 보완·판매망·원가 절감의 시너지가 매도자에게도 가격으로 일부 배분되면, 수익성이 좋은 기업의 매각도 합리적 선택이 될 수 있음.''',('linear_defm14a','linear_deal','linear_close'),flow([('2015','초기 접근·제안 거절'),('2016 상반기','재협상·다른 매수자 검토'),('2016.07','현금 + 주식 합의'),('2017.03','ADI 인수 완료')],'합병 위임장 및 ADI 발표에 근거한 거래 순서'))

sec('01 리니어의 역사','linear-context','왜 통합이 선택되었나: 세 가지 환경','기업의 강점이 사라지지 않아도 독립 경영의 상대적 매력은 낮아질 수 있음.', '''첫째는 성장 기회의 변화임. 성숙한 고성능 아날로그 사업은 좋은 현금창출원이었으나, 좁은 제품 영역만으로 고성장을 재현하기는 어려웠음. 산업용·자동차용 고객의 복잡한 설계를 지원하려면 단일 칩 성능뿐 아니라 여러 부품과 소프트웨어를 결합한 해결 능력이 중요해졌음.

둘째는 규모와 범위의 경제임. 제품군을 넓히면 동일한 고객에게 더 많은 부품을 판매할 수 있고, 설계 지원·판매망·연구개발의 일부 비용을 공유할 수 있음. 이것이 모든 인수를 성공시키는 것은 아니며, 조직 통합 비용과 높은 인수가격이 시너지를 상쇄할 수 있음. 실제 성과는 인수 이후 현금흐름으로 검증해야 함.

셋째는 금융 환경임. 금융위기 이후 낮은 금리는 대규모 차입 인수의 부담을 낮추고 장기 현금흐름의 현재가치를 높였음. 다만 금리가 낮아서 인수되었다는 단일 원인 설명은 부족함. 제품 보완성, 매도자의 독자 전망, 매수자의 자금조달 능력, 인수 프리미엄이 함께 맞아야 거래가 성립함.''',('linear_deal','linear_defm14a','fed_history'),callout('해석의 범위','리니어는 배당 때문에 소멸한 기업이 아니라, 높은 수익성을 가진 성숙기업이 산업 통합 과정에서 매각을 선택한 사례로 읽는 것이 타당함.'))

sec('01 리니어의 역사','lifecycle','기업의 생애주기와 재성장 가능성','성숙기는 쇠락의 예약이 아니라 자본배분의 분기점임.', '''스타트업은 제품의 가능성을 검증하느라 현금을 소모함. 유년기에는 초기 고객과 생산 체계를 만들며, 성장기에는 매출 증가를 따라잡기 위해 인력·재고·설비에 투자함. 성숙기에 접어들면 투자 기회보다 내부 현금창출이 커질 수 있음. 쇠락기는 기존 제품의 수요와 경제적 가치가 줄어드는 구간임.

이 순서는 이해를 위한 모형이며 모든 기업이 같은 속도로 이동하는 것은 아님. 성숙기의 현금을 R&D·인수·신규 시장 진입에 배분해 다시 성장할 수도 있음. 반대로 유망해 보이는 투자라도 자본비용을 넘는 수익을 내지 못하면 기업가치를 파괴함. 재성장은 투자 지출 자체가 아니라 투자 이후의 경쟁력과 현금흐름으로 판별해야 함.

성숙기업의 배당은 성장 포기의 증거가 아니며, 성장기업의 무배당도 좋은 투자안을 보장하지 않음. ‘얼마나 환원했는가’보다 ‘유지해야 할 경쟁력, 투자할 기회, 불황을 버틸 현금이 충분한가’를 먼저 묻는 편이 유용함. 리니어의 사례는 이 구분을 실제 거래와 연결해서 볼 수 있게 해 줌.''',('linear_10k_2016',),'<figure><svg viewBox="0 0 900 310" role="img" aria-label="기업 생애주기와 재성장 개념도"><path d="M45 255H870 M45 255V25" stroke="#607b92" fill="none"/><path d="M50 245 C150 248 210 218 300 145 S430 67 555 70 S720 95 850 214" fill="none" stroke="#37ccff" stroke-width="5"/><path d="M550 70 C640 95 675 12 850 22" fill="none" stroke="#39e2b0" stroke-width="5" stroke-dasharray="9 6"/><text x="600" y="130" fill="#39e2b0">R&amp;D·신사업·인수 → 재성장 가능</text><text x="55" y="285">스타트업</text><text x="220" y="285">유년기</text><text x="390" y="285">성장기</text><text x="570" y="285">성숙기</text><text x="770" y="285">쇠락</text><text x="55" y="22">사업 규모</text></svg><figcaption>개념도 · 실측 시계열이 아니며 재성장을 보장하지 않음</figcaption></figure>')
sec('02 반도체 산업의 변천','history-map','반도체 역사를 읽는 다섯 개의 수요 시대','수요·기술·기업·자본의 변화를 같은 시간축에서 볼 필요 있음.', '''시대 구분은 기술의 발명 연도만으로 정해지지 않음. 발명된 기술이 큰 시장을 만나고, 생산 규모가 커지며, 그 규모를 감당할 금융 구조가 만들어질 때 산업의 중심이 바뀜. PC가 등장했다고 국방 수요가 사라진 것은 아니며, AI가 커져도 자동차·산업용·스마트폰 수요는 계속 존재함. 구분은 지배적인 성장동력을 설명하기 위한 틀임.

큰 흐름은 국방·우주와 초기 컴퓨팅, PC와 일본의 부상, 인터넷과 분업화, 모바일·클라우드와 메모리 과점, AI와 대규모 데이터센터 투자로 나눌 수 있음. 각 시기 내부에도 호황과 불황이 있음. 같은 2010년대라도 2012년 메모리 위기, 2017~2018년 호황, 2019년 조정은 재무적 의미가 완전히 다름.

매출 순위를 볼 때도 범위를 고정해야 함. 반도체 공급업체 매출, 회사 전체 매출, 파운드리 매출, 장비 매출은 다른 시장임. 삼성의 스마트폰 매출과 NVIDIA의 GPU 매출, TSMC의 위탁생산 매출을 섞으면 비교 의미가 흐려짐. 업계 순위에 TSMC가 보이지 않는 것은 경쟁력이 없어서가 아니라 집계 범위가 다를 수 있음.''',('ranking_history','WSTS'),table(['큰 시기','세부 구간','수요 중심','재무적 질문'],[['태동기','1947–1959 / 1960s / 1970s','국방·우주·메인프레임·계산기','누가 초기 기술 위험을 부담하는가'],['제1기','1980–1985 / 1986–1991','PC·DRAM','누가 비싼 투자를 오래 지속하는가'],['제2기','1992–1999 / 2000–2007','PC·인터넷·디지털기기','설계와 제조 위험을 어떻게 나누는가'],['제3기','2008–2012 / 2013–2016 / 2017–2019','모바일·클라우드','불황과 부채 만기를 버틸 수 있는가'],['제4기','2020–2023 / 2024–현재','AI·GPU·HBM·인프라','누가 최종 수요의 현금을 지불하는가']]))

sec('02 반도체 산업의 변천','origin-invention','태동기 ① 1947–1959: 발명에서 제조기술로','트랜지스터와 집적회로는 서로 다른 단계의 혁신임.', '''1947년 벨연구소에서 트랜지스터가 개발되었음. 진공관보다 작고 전력 소비가 낮으며 신뢰성을 높일 수 있는 소자였음. 처음에는 하나의 소자를 잘 만드는 일이 중요했으나, 복잡한 전자기기를 만들려면 수많은 부품을 연결해야 한다는 문제가 남았음. 부품 수 증가가 배선 비용과 고장 가능성을 높였음.

1958년 TI의 잭 킬비는 여러 소자를 하나로 집적한 회로를 시연했으며, 1959년 페어차일드의 로버트 노이스는 실리콘 위에서 소자를 연결하는 양산에 유리한 접근을 제시했음. 집적회로는 단순한 소형화가 아니라 부품 제작과 연결을 일괄 공정으로 바꾼 혁신이었음. 이후 생산량 증가와 수율 개선이 단가 하락으로 이어질 기반이 만들어졌음.

벨연구소에서 쇼클리 반도체 연구소, 페어차일드, 인텔 등으로 이어지는 인력과 지식의 이동이 중요했음. 다만 모든 회사를 벨연구소의 직접 분사로 묶으면 부정확함. 기업마다 창업 경로와 기술·자금의 출처가 달랐음. 연구 성과, 특허, 숙련 인력, 초기 고객이 결합해 지역 생태계를 형성한 과정으로 이해할 수 있음.''',('transistor','kilby','noyce'),flow([('트랜지스터','개별 소자의 혁신'),('집적회로','연결을 칩 안으로 통합'),('평면 공정','반복 생산과 수율 개선'),('규모 확대','단가 하락·응용 확산')]))

sec('02 반도체 산업의 변천','origin-state','태동기 ② 1960년대: 정부가 초기 시장을 만들었음','최저 가격보다 크기·무게·신뢰성이 중요한 고객이었음.', '''초기 IC는 개별 트랜지스터보다 비쌌고 대체하는 부품 수도 많지 않았음. 그럼에도 미사일·우주선에서는 작은 크기와 낮은 전력 소비의 가치가 컸음. 미국 국방부와 NASA의 조달은 민간 소비재 시장이 충분히 커지기 전에 생산량과 품질을 개선할 기회를 제공했음.

아폴로 유도컴퓨터와 미니트맨 프로그램은 대표적인 초기 수요였음. 컴퓨터역사박물관의 기록에 따르면 아폴로 유도컴퓨터 프로젝트는 1965년까지 주요 IC 구매처였고, 이후 미니트맨의 조달 규모가 이를 넘어섰음. 중요한 것은 국방비 전체 증가가 반도체 매출 증가와 일대일로 같다는 뜻이 아니라, 특정 프로그램의 구매가 신기술의 학습곡선을 앞당겼다는 점임.

원가보상 방식의 연구개발 계약은 일부 기술 위험을 정부와 공유할 수 있었음. 그러나 모든 군수 조달이 동일한 Cost-Plus 계약이었거나 손실을 무조건 보장했다고 일반화하면 안 됨. 계약별 비용 인정 범위, 성과 조건, 생산가격 협상은 달랐음. 정부의 역할은 보조금뿐 아니라 신뢰할 만한 초기 고객, 연구개발 발주자, 표준과 품질 요구의 설정자였음.''',('chm_early','CHM'),callout('현대 산업정책과의 연결','정부가 공장을 지원하는 것과 공장에서 나올 제품의 구매를 약속하는 것은 다른 정책임. 전자는 투자비를 낮추고, 후자는 수요 불확실성을 낮춤.'))

sec('02 반도체 산업의 변천','origin-commercial','태동기 ③ 1970년대: 메모리와 마이크로프로세서','전용 회로에서 범용 플랫폼으로 시장이 넓어졌음.', '''1970년 인텔의 1103 DRAM, 1971년 4004 마이크로프로세서는 상용 반도체의 중요한 이정표임. DRAM은 정보를 저장하는 소자를 대량 생산하는 시장을 열었고, 마이크로프로세서는 소프트웨어로 기능을 바꿀 수 있는 계산 장치를 한 칩으로 구현했음. 계산기·산업기기·컴퓨터로 고객 기반이 넓어졌음.

1965년 무어가 제시한 집적도 증가에 대한 관찰은 이후 산업의 기술 로드맵이 되었음. 처음의 관찰과 나중에 정착한 ‘약 2년마다 두 배’라는 표현은 구분할 필요 있음. 이는 자연법칙이 아니라 연구개발·설비·시장 수요가 함께 지탱한 경험적 경향임. 공정이 발전할수록 칩당 비용이 항상 자동으로 줄어드는 것도 아님.

한국에서는 1974년 삼성의 한국반도체 인수가 중요한 출발점이 되었음. 이후 단순 조립을 넘어 설계·공정·양산 능력을 확보하는 과정이 이어졌음. 초기 진입은 작은 기술 획득과 인력 축적에서 시작했으나, 메모리 대량생산 경쟁에 참여하면서 필요한 자본과 실패 비용이 크게 커졌음.''',('intel_4004','moore1965','samsung_history'))

sec('02 반도체 산업의 변천','pc-us-japan','제1기 ① 1980–1985: PC 혁명과 미·일 경쟁','수요 확대와 자본비용 충격이 동시에 나타났음.', '''1981년 IBM PC는 개인용 컴퓨터의 대중화와 표준 형성에 큰 영향을 주었음. PC 판매가 늘면서 프로세서뿐 아니라 DRAM·주변 칩에 대한 수요도 증가했음. 이 시기의 경쟁은 제품 발명만이 아니라 높은 수율로 대량 생산하고 공급을 안정적으로 이어가는 능력을 요구했음.

미국은 인플레이션 억제를 위해 강한 통화긴축을 시행했음. 연방기금금리는 1981년 중반 약 19% 수준에 이르렀음. 높은 금리는 투자안의 할인율과 차입 부담을 높임. 동시에 경기 침체와 달러 강세가 기업의 수요·수출 경쟁력에 영향을 주었음. 금리 하나만으로 국가별 반도체 경쟁력을 설명할 수는 없지만 장기투자에 불리한 환경이었던 것은 분명함.

일본 기업들은 은행 관계, 그룹 내부자금, 생산관리와 품질 개선, 정부의 연구개발 협력 등을 활용했음. 미국 기업의 모든 CAPEX가 축소되고 일본만 무제한 투자했다는 식의 설명은 과도함. 일본의 DRAM 부상에는 자본의 안정성뿐 아니라 수율·품질·고객 신뢰라는 제조 경쟁력이 결합했음. 인텔의 DRAM 철수와 프로세서 집중은 이에 대한 전략적 재배치였음.''',('volcker','intel_dram','ranking_history'),callout('금리의 전달 경로','정책금리 → 국채·회사채 금리 및 환율 → 차입비용과 할인율 → 투자 규모·시점 → 다음 세대 생산능력으로 이어짐. 중간 단계마다 기업별 차이가 존재함.'))

sec('02 반도체 산업의 변천','pc-korea-trade','제1기 ② 1983–1991: 한국의 진입과 무역 갈등','낮은 원가로 양산할 때까지 버티는 시간이 필요했음.', '''삼성은 1983년 메모리 반도체에 본격 진입했고 같은 해 64K DRAM 개발에 성공했음. 기술을 도입하는 것과 수익성 있는 대량생산을 하는 것은 다른 단계였음. 설비가 가동되기 전에 큰 금액을 지출해야 했고, 초기 수율이 낮으면 생산을 많이 해도 손실이 날 수 있었음. 그룹의 자금 동원력과 장기 의사결정이 중요했으나 그 자체가 성공을 보장하지는 않았음.

1986년 미·일 반도체 협정과 1991년의 후속 협정은 덤핑·시장 접근·무역 불균형 문제와 연결되어 있었음. 가격과 시장접근 조건에 영향을 주었지만 일본 산업의 후퇴를 협정 하나로 설명하기는 어려움. 이후 PC 중심의 수요 변화, 설계와 제조의 분업, 일본의 장기 경기 침체, 한국·대만의 추격이 함께 작용했음.

1990년대 초반까지 NEC·Toshiba·Hitachi 등 일본 기업은 상위권에 있었음. 이후 Intel의 프로세서 지배력, 삼성의 메모리 제조 능력, 대만의 파운드리 생태계가 서로 다른 방식으로 성장했음. 국가별 승패를 하나의 숫자로 요약하기보다 어느 제품과 가치사슬 단계에서 경쟁력이 이동했는지 나눠 보는 편이 정확함.''',('samsung_history','ranking_history','intel_dram'))

sec('02 반도체 산업의 변천','internet-foundry','제2기 ① 1987–1999: 인터넷 확대와 분업의 경제성','설계 진입비용을 낮추는 대신 제조의 규모를 더 크게 만들었음.', '''TSMC는 1987년 전용 파운드리 사업 모델을 개척했음. 자체 브랜드 칩을 팔지 않고 고객 설계의 제조를 맡는 원칙은 고객과의 경쟁 우려를 줄였음. 설계기업은 공장 없이 제품 개발에 집중할 수 있었고, 파운드리는 여러 고객의 물량을 모아 설비를 더 효율적으로 활용할 수 있었음.

1990년대 PC와 인터넷 확산은 칩 설계의 종류와 수요를 늘렸음. 동시에 공정이 미세해지면서 장비·공장·기술 개발의 비용이 증가했음. 모든 기업이 설계부터 제조까지 소유하기보다, 전문화된 기업들이 각 단계의 고정비를 여러 고객에 나누어 부담하는 구조가 유리해졌음. NVIDIA·Qualcomm 같은 팹리스의 성장과 TSMC의 성장은 서로를 필요로 했음.

분업은 산업 전체의 투자비를 없앤 것이 아님. 공장 투자는 파운드리에 집중되고 설계기업에는 선단공정 접근, 생산능력 확보, 선급금, 고객 수요 예측이라는 다른 위험이 남았음. 제조 위험을 외부에 맡긴 만큼 특정 공급자·공정·지역에 대한 의존도도 높아졌음. 자본 효율과 공급망 취약성이 동시에 커지는 변화였음.''',('foundry_model','tsmc1998'),flow([('설계 전문화','아이디어·IP·인력'),('제조 수요 집적','여러 고객의 주문'),('공정 전문화','수율·장비·대형 CAPEX'),('생태계 확대','새 팹리스의 진입')]))

sec('02 반도체 산업의 변천','valuechain','수직적 분업의 지도: 칩 한 개가 나오는 과정','회사 이름보다 어떤 자산과 위험을 소유하는지 먼저 보는 편이 유용함.', '''반도체의 분업은 ‘설계 회사와 공장’ 두 칸으로 끝나지 않음. 칩을 기획한 뒤 CPU 구조 같은 IP를 사용하고, EDA 도구로 회로를 설계·검증하며, 파운드리에 제조를 맡기고, 패키징·테스트를 거쳐 시스템에 탑재함. 소재·장비 회사는 여러 단계에 생산 수단을 공급함. 모든 기업이 한 역할만 하는 것도 아니며, 사업부에 따라 역할이 겹침.

IP 기업은 검증된 설계 자산을 라이선스하거나 판매량에 따라 로열티를 받음. EDA 기업은 설계와 검증 소프트웨어를 제공함. 팹리스는 제품과 고객 관계, 설계 차별화에 집중함. 파운드리는 공정 개발과 웨이퍼 제조, 수율과 대량생산을 책임짐. OSAT는 조립·패키징·테스트를 전문적으로 수행함. IDM은 설계와 제조를 함께 보유하는 모델임.

HBM과 첨단 패키징에서는 경계가 다시 겹치고 있음. 메모리 회사가 HBM 적층을 수행하고, 파운드리가 GPU와 HBM을 통합하는 패키징 서비스를 제공하며, OSAT도 고도화된 패키징에 참여함. 분업은 완전 분리가 아니라 인터페이스를 중심으로 역할이 조정되는 과정임. 병목 단계가 바뀌면 협상력과 이익의 배분도 달라짐.''',('foundry_model','tsmc_annual','hbm_definition'),table(['단계','하는 일 · 쉬운 비유','대표 기업 예시','주요 자본·재무 위험'],[['IP','반복 사용 가능한 설계 블록 · 설계도 부품','Arm · Synopsys IP','R&D 선투자·라이선스/로열티 의존'],['EDA','회로를 설계하고 검증하는 도구 · 건축 설계 프로그램','Synopsys · Cadence · Siemens EDA','개발인력·기술 전환·고객 집중'],['팹리스','칩 제품 설계와 판매 · 설계사','NVIDIA · Qualcomm · AMD · MediaTek','R&D·재고·선급금·제조사 의존'],['파운드리','고객 설계의 웨이퍼 제조 · 전문 건설사','TSMC · Samsung Foundry · UMC · GlobalFoundries','대규모 CAPEX·수율·가동률'],['IDM','설계와 제조 통합 · 설계와 공장을 함께 소유','Intel · Samsung 메모리 · SK hynix · Micron · TI','설계·제조 위험 동시 부담'],['OSAT','패키징과 테스트 · 완제품 조립·검수','ASE · Amkor · JCET','설비·첨단 패키징 전환·고객 집중'],['장비','노광·증착·식각·검사 장비','ASML · Applied Materials · Lam Research · KLA · Tokyo Electron','R&D·수출통제·고객 투자주기'],['소재','웨이퍼·가스·화학재료·레지스트','Shin-Etsu · SUMCO · Entegris · JSR','고객 인증·품질·원재료·증설'],['시스템·클라우드','칩을 서버·제품에 통합해 서비스 제공','Apple · Microsoft · Amazon · Google','설비와 서비스 수요의 시차']]))

sec('02 반도체 산업의 변천','internet-crash','제2기 ② 2000–2007: 닷컴 붕괴와 새로운 수요','성장 전망을 믿고 만든 설비는 수요가 사라져도 남음.', '''인터넷과 통신망에 대한 기대가 높아지면 서버·네트워크 장비·광통신 설비의 주문이 앞당겨짐. 공급자는 이를 근거로 생산능력을 확대하고, 고객은 자금조달을 통해 네트워크를 구축함. 최종 고객의 지불 의사와 서비스 매출이 기대에 못 미치면 설비·재고·차입이 동시에 부담으로 바뀜. 닷컴 붕괴는 기술의 효용과 투자 가격의 적정성이 별개라는 점을 보여 줌.

반도체 시장은 2001년 큰 폭으로 감소했으나 인터넷 자체가 사라진 것은 아니었음. 이후 디지털 카메라, MP3, 게임기, 휴대전화 등 여러 기기가 새 수요를 만들었음. 반도체의 장기 성장과 투자 시점의 수익률을 같은 것으로 생각하면 안 되는 이유임. 좋은 기술도 너무 높은 가격과 과도한 설비 투자에서는 나쁜 재무 결과를 낼 수 있음.

분업화는 이 시기에도 계속되었음. 공장 건설 비용이 커질수록 기업은 자사 공정의 범위를 줄이거나 외부 제조를 활용했음. 단, 메모리와 아날로그처럼 제조 기술이 제품 경쟁력과 밀접한 분야에서는 IDM 모델이 계속 중요했음. 산업의 모든 영역이 동일한 팹리스 모델로 수렴한 것은 아님.''',('WSTS','foundry_model'),callout('사이클의 기본 구조','수요 기대 증가 → 선행 투자·중복 주문 → 공급 도착 → 수요 둔화·재고 증가 → 가격 하락·투자 축소 → 공급 조정이라는 순환이 반복될 수 있음.'))

sec('02 반도체 산업의 변천','memory-crisis','제3기 ① 2008–2012: 금융위기와 메모리 재편','불황에 버틴다는 것은 현금·원가·기술을 함께 유지하는 것임.', '''금융위기는 최종 수요와 금융시장을 동시에 위축시켰음. 메모리는 비교적 표준화된 제품이므로 공급이 수요를 조금만 초과해도 가격이 크게 하락할 수 있음. 이미 지은 공장은 감가상각과 유지비가 발생하며, 기술 세대가 뒤처지면 원가 경쟁력도 나빠짐. 투자를 줄여 현금을 지키는 선택과 투자를 이어가 미래 원가를 낮추는 선택이 충돌하는 시기였음.

삼성은 메모리 이외의 사업과 내부 현금창출, 제조 규모를 바탕으로 불황에 대응할 여력이 있었음. 그렇다고 모든 시기에 투자 규모를 전혀 줄이지 않았다고 단순화하면 부정확함. 투자 계획은 업황과 기술 전환에 맞춰 조정되었음. 중요한 것은 특정 연도 지출액보다 경쟁사가 탈락하거나 후퇴할 때 다음 세대 양산을 유지할 능력이 있었는지임.

이 과정을 흔히 치킨게임이라고 부르지만, 상대를 쓰러뜨리려고 손실을 무한정 감수하는 단일 전략으로 보는 것은 과도함. 각 회사는 수요 전망·원가·자금조달·기술 로드맵을 고려해 투자함. 결과적으로 자금과 기술의 여력이 약한 기업이 퇴출되고 생존 기업에 점유율이 집중될 수 있음. 산업 집중은 개별 기업의 의도와 시장 결과를 구분해서 해석해야 함.''',('elpida_sec','samsung_ir','ranking_history'))

sec('02 반도체 산업의 변천','elpida','엘피다: 만기 위험은 기술 경쟁력과 별개로 작동함','가격 하락·엔고·손실·차환 위험이 중첩된 사례임.', '''엘피다는 일본의 주요 DRAM 기업이었으며 2012년 회사갱생 절차를 신청했음. 수요와 가격 약화, 엔화 강세, 경쟁사의 비용 우위, 투자 부담과 만기 도래 등이 겹쳤음. 이를 ‘단기 차입을 많이 써서 파산함’이라는 한 문장으로 줄이면 원인이 지나치게 단순해짐. 장기채권도 만기가 가까워지면 유동부채가 되므로 원래 단기조달인지 만기 도래분인지 구분해야 함.

공장은 장기간 사용하며 현금으로 회수하는 자산임. 반면 차입은 정해진 날짜에 이자와 원금을 지급해야 함. 사업의 장기 가치가 양수여도 상환일에 현금이 부족하고 차환이 막히면 기업은 회생 절차에 들어갈 수 있음. 이때 자산과 기술이 사라지는 것이 아니라 소유권과 부채 구조가 재편될 수 있음.

Micron은 2013년 엘피다 인수를 완료했음. 첨단 DRAM 자산과 고객 관계가 경쟁사 체계로 편입되면서 글로벌 산업은 더 집중되었음. 여기서 얻을 교훈은 ‘차입이 많은 회사가 항상 먼저 탈락함’이 아니라, 가격 충격을 견딜 영업현금과 만기 구조, 추가 자금조달 능력이 생존을 좌우할 수 있다는 것임. 높은 부채에도 장기 고정금리와 안정적 현금을 확보한 기업은 결과가 다를 수 있음.''',('elpida_sec','elpida_done'),flow([('장기 자산','공장·장비·기술개발'),('수익 변동','가격 하락·환율·가동률'),('지급 의무','이자·원금 만기'),('차환 실패','유동성 위기·소유권 재편')]))

sec('02 반도체 산업의 변천','hynix-mobile','제3기 ② 2012–2016: 모바일·클라우드와 자본의 후원자','SK 편입은 사업과 재무의 시간을 길게 만드는 계기였음.', '''하이닉스는 2001년 이후 채권단 관리와 구조조정을 겪었고 2012년 SK그룹에 편입되었음. 인수 대금 약 3.4조 원에는 기존 주식 취득과 신주 인수가 포함되므로, 전체 금액이 회사로 들어온 신규 자본은 아님. 지배주주의 자금 동원력과 신용 기반, 장기 투자 의지가 강화되었다는 점과 실제 유입 현금은 따로 봐야 함.

스마트폰 보급은 모바일 DRAM과 NAND의 수요를 확대했음. 클라우드는 여러 기업의 서버 투자를 대형 사업자에 집중시켰으며, 대규모 고객의 성능·전력·납기 요구가 중요해졌음. 고객 수가 적고 주문 규모가 커질수록 공급자에게 기회와 집중 위험이 함께 생김. 기술 인증에 성공하면 큰 매출이 가능하지만 한 고객의 주문 조정도 영향이 커짐.

금융위기 이후의 낮은 금리는 투자의 할인율과 차입비용을 낮추었음. 반도체 M&A도 활발해졌으며, 2015~2016년에는 넓은 제품군과 고객 기반을 확보하려는 거래가 이어졌음. 리니어의 매각은 이 환경 안에 있었음. 같은 저금리라도 자금이 설비투자·인수·자사주 매입 중 어디로 배분되는지는 기업의 사업 단계에 따라 달랐음.''',('MAXIM','linear_deal','fed_history','sk_ir'))

sec('02 반도체 산업의 변천','memory-supercycle','제3기 ③ 2017–2019: 과점 이후에도 가격 사이클은 남았음','집중도가 높아졌다고 안정적인 이익이 보장되는 것은 아님.', '''삼성·SK하이닉스·Micron 중심의 DRAM 과점은 공급자의 수를 줄였음. 그러나 DRAM과 NAND는 별개의 시장이며, ‘메모리 Big 3’라는 표현을 모든 메모리 제품의 동일한 점유 구조로 이해하면 안 됨. NAND에는 Kioxia와 Western Digital 계열 등 다른 주요 생산자가 존재함.

2017~2018년 메모리 가격 상승은 매출과 이익을 크게 끌어올렸음. 삼성의 반도체 매출 순위 상승에는 출하량·기술뿐 아니라 가격의 영향도 컸음. 반대로 2019년 조정에서는 가격 하락과 재고 증가가 매출과 이익에 부담을 주었음. 순위가 바뀌었다는 사실만으로 장기 기술 우위가 같은 폭으로 바뀌었다고 해석하면 안 됨.

과점 시장에서도 개별 기업은 기술 전환, 고객 확보, 다음 세대 원가를 위해 투자함. 모든 회사가 합리적으로 판단해도 공급이 비슷한 시기에 늘면 가격이 흔들릴 수 있음. 따라서 고점 이익을 영구적인 현금창출로 가정해 배당·자사주·차입 한도를 정하면 위험함. 정상화된 가격과 여러 해의 투자 필요를 함께 반영해야 함.''',('ranking_2017','WSTS','micron_memory'))

sec('02 반도체 산업의 변천','pandemic','제4기 ① 2020–2023: 공급 부족에서 재고 조정으로','같은 반도체 안에서도 부족한 제품과 남는 제품이 달랐음.', '''팬데믹은 재택근무와 디지털 기기 수요를 늘리고 물류·공장 운영을 교란했음. 자동차용 MCU나 일부 아날로그 제품은 공급 부족을 겪었지만, 모든 종류의 반도체가 같은 방식으로 부족했던 것은 아님. 특정 공정·패키지·공장 인증에 묶인 제품은 다른 공장의 빈 생산능력으로 즉시 대체하기 어려웠음.

공급 부족 때 고객은 안전재고를 늘리거나 중복 주문을 넣을 유인이 있음. 생산자는 주문 잔고를 수요로 해석하고 증설함. 납기가 정상화되고 최종 수요가 둔화되면 주문이 줄고 재고가 쌓임. 2022~2023년의 조정은 장기 수요 증가 전망과 단기 공급·재고 불균형이 함께 존재할 수 있음을 보여 줌.

2022년 이후의 통화긴축은 자금조달비용과 기술기업 가치평가에 영향을 주었음. 동시에 각국은 반도체 생산을 전략산업으로 보고 보조금과 세액공제를 확대했음. 시장금리는 높아져도 특정 프로젝트의 보조금으로 투자 부담이 낮아지는 상황이 가능함. 기업의 실제 자본비용은 기준금리 하나로 결정되지 않음.''',('WSTS','fed_history','tsmc_annual'))

sec('02 반도체 산업의 변천','ai-architecture','제4기 ② 2024–현재: GPU에서 메모리·패키징·전력으로','연산칩만 늘려서는 데이터센터가 완성되지 않음.', '''생성형 AI는 대규모 병렬 연산과 빠른 데이터 이동을 필요로 함. GPU 성능이 올라가도 데이터를 충분히 공급하지 못하면 연산기가 기다리게 됨. GPU 가까이에 HBM을 배치하고 넓은 연결 통로를 만드는 이유임. HBM은 DRAM을 적층하고 연결 구조를 개선한 고부가 제품이며, 모든 일반 DRAM을 즉시 대체하는 것은 아님.

AI 서버가 늘면 CPU와 시스템 DRAM, 저장장치용 NAND, 네트워크 칩, 전력관리, 냉각, 첨단 패키징의 수요도 영향을 받음. 다만 품목별 수요 강도와 공급 제약이 다르고, 학습과 추론의 구조도 다름. AI 수요 증가가 모든 반도체 제품에 같은 성장률과 마진을 보장한다고 생각하면 안 됨.

가치가 병목에 집중되는 경향이 있음. GPU 설계·소프트웨어 생태계, 선단공정, HBM, 첨단 패키징처럼 단기간 대체가 어려운 능력을 가진 공급자는 유리한 협상력을 확보할 수 있음. 이익률이 높아지면 신규 투자와 경쟁도 유입됨. 현재의 초과이익이 얼마나 오래 지속될지 판단하려면 고객 인증·기술 세대·증설 기간을 함께 살펴야 함.''',('hbm_definition','nvidia_annual','tsmc_annual'),flow([('GPU','병렬 연산'),('HBM','GPU 근접 고대역폭 메모리'),('DRAM·NAND','서버 작업공간·저장'),('네트워크·전력','데이터 이동·운영 기반')],'AI 데이터센터 수요의 확산 · 인과관계 개념도'))

sec('02 반도체 산업의 변천','history-lessons','역사에서 남는 네 가지 재무 원리','기술의 성공과 주주의 수익, 기업의 생존을 구분할 필요 있음.', '''수요 중심이 바뀌면 상대적 성장률과 협상력이 바뀜. PC의 Intel, 메모리 호황기의 삼성, AI 인프라의 NVIDIA는 각기 다른 수요와 사업 모델을 대표함. 다만 특정 시기의 매출 1위가 모든 분야의 기술 1위를 의미하지는 않음. 아날로그는 모든 기기에 필수였지만 리니어의 좁은 제품 영역은 산업 전체의 폭발적 성장과 같은 속도로 커지지 않았음.

메모리에서는 가격이 순위와 이익을 크게 바꿈. 같은 생산량이라도 가격이 떨어지면 현금흐름은 급감할 수 있음. 불황의 자금 여력은 다음 세대 투자와 고객 관계를 유지할 시간을 제공함. 그러나 자금만으로 기술 격차를 무조건 극복할 수는 없으므로, 원가·수율·제품 경쟁력과 함께 판단해야 함.

투자는 장기지만 지급 의무는 특정 시점에 집중될 수 있음. 만기를 분산하고 안정적 자금을 확보하는 일은 사업 전망만큼 중요함. 또한 금리·환율·보조금·수출통제는 기업의 자본비용과 시장 접근을 바꿈. 기업재무를 산업과 거시환경에서 떼어 놓으면 같은 투자안이 왜 시기별로 다른 가치를 갖는지 설명하기 어려움.''',('ranking_history','elpida_sec','fed_history'))
