for name,c in R['companies'].items():
 t=c['latestTTM']; finrows.append([name,f"{t['revenue']:,.1f}",f"{t['operatingCF']:,.1f}",f"{t['capex']:,.1f}",f"{t['fcf']:,.1f}"])
sec('03 AI 시대의 재무 이슈','buyer-cash','이슈 1. 수요자의 재무: 모든 빅테크가 적자는 아님','투자 부담과 지불 능력을 회사별로 분리해서 봐야 함.', '''빅테크의 AI 인프라 투자가 반도체 호황의 주요 출발점임. 2026년 최신 CAPEX 가이던스는 Microsoft 약 1,700억 달러, Amazon 약 2,200억 달러, Alphabet 1,950억~2,050억 달러, Meta 1,350억~1,450억 달러로 합계 7,200억~7,400억 달러임. 다만 회사별로 리스와 현금 지출의 포함 범위가 다르며, 이 합계는 이미 집행된 금액이 아님.

CAPEX가 커지면 당기 현금은 바로 유출되지만 손익계산서에는 여러 해의 감가상각으로 나뉘어 반영됨. 따라서 영업이익이나 순이익이 높아도 FCF는 빠르게 줄어들 수 있음. 반대로 기존 광고·소프트웨어·전자상거래 사업의 현금창출이 크면 대규모 AI 투자에도 FCF가 양수일 수 있음. ‘빅테크 전체가 FCF 적자’라는 설명은 실제 회사별 차이를 지움.

2026년 9월 말까지 12개월의 현금 CAPEX를 같은 방식으로 정규화하면 Amazon은 FCF가 음수이고 나머지 세 회사는 양수임. Meta의 3분기 단일분기 FCF가 적자였다는 사실과 최근 12개월 FCF가 양수라는 사실은 모순이 아님. 분석 기간과 계산 정의가 다르기 때문임. Amazon의 회사 자체 FCF와 아래 값도 자산처분·인센티브 등 CAPEX 조정으로 차이가 남.''',('msq1','amznq3','googq3','metaq3'),table(['2026.09 TTM · $bn','매출','영업현금흐름','총현금 CAPEX','정규화 FCF'],finrows)+callout('비교 정의','FCF = 영업현금흐름 − 총 현금 유형자산 취득액. 비현금 리스 증가와 금융리스 원금은 제외함. 회계연도 표시는 Microsoft 6월, 다른 세 회사 12월 종료임. TTM은 2026년 9월 말 최근 12개월이며 연간 전망과 다름.'))

charts=''
for name,c in R['companies'].items():
 arr=[x for x in c['annual'] if x['year']>=2021]
 charts+=linechart(name+' · 현금투자와 FCF',[str(x['year']) for x in arr],[('CAPEX',[x['capex'] for x in arr],'#37ccff'),('FCF',[x['fcf'] for x in arr],'#ffb15e')],'십억 달러 · 회사 회계연도 실적')
sec('03 AI 시대의 재무 이슈','buyer-trends','투자·현금흐름·부채를 함께 읽는 방법','손익이 좋다는 사실만으로 투자 지속 능력을 판정할 수 없음.', '''CAPEX는 기업의 장기 경쟁력을 위해 필요할 수 있으나, 현금 유출의 규모와 시점이 중요함. 신규 데이터센터가 매출을 만들기 전에 전력·건물·서버 지출이 발생함. 서비스 수익화가 늦어지면 투자와 회수의 간격을 내부 현금, 회사채, 금융리스 또는 파트너 자금으로 메워야 함.

부채 잔액과 회사채 발행액은 다른 지표임. 연말 부채가 증가하지 않아도 만기 채권을 상환하고 새 채권을 발행했을 수 있음. 현금흐름표의 차입 수취액도 단기차입의 반복 조달이 포함되면 시장의 장기 회사채 발행액과 같지 않음. 비교 시 신규 조달·상환·순증액·잔액을 분리해야 함.

아래 그래프는 공시의 총현금 CAPEX와 영업현금흐름에서 계산한 FCF임. 급격한 투자 확대가 FCF를 줄이는 방향은 보이지만 그것만으로 가치파괴라고 결론내릴 수는 없음. 신규 설비의 가동률, 단위 연산당 수익, 기존 고객의 사용 확대, 가격 인하 속도를 통해 향후 회수를 검증해야 함. 주가나 매출 성장만으로 자금의 지속 가능성을 판정하지 않는 것이 핵심임.''',('msq1','amznq3','googq3','metaq3'),charts)

sec('03 AI 시대의 재무 이슈','seven-checks','빅테크 재무 건전성의 일곱 가지 점검 항목','하나의 경고 신호보다 지표들이 함께 악화되는지를 보는 방식임.', '''첫 번째 질문은 투자가 매출보다 먼저 늘어나는 정상적인 확장인지, 매출이 따라오지 못하는 과잉인지임. 클라우드 매출 성장률과 CAPEX를 비교하되, 회사 전체 CAPEX에는 다른 사업 투자도 포함될 수 있음을 고려해야 함. 수주잔고가 커져도 계약 기간과 해지권, 고객의 자금조달에 따라 현금 회수의 확실성은 달라짐.

두 번째 질문은 투자 둔화 없이도 지급 의무를 견딜 수 있는지임. FCF, 이자보상배율, 차입 만기, 현금과 유동성 한도를 함께 봐야 함. 총부채/자기자본 비율에는 영업 부채도 포함되므로 이자부 차입금 비율과 같은 것으로 읽으면 안 됨. 자사주 매입으로 자기자본이 작아지면 비율이 높아질 수 있음.

마지막 질문은 회계상 이익과 경제적 회수가 일치하는지임. 서버 내용연수 연장은 감가상각을 줄여 당기 이익을 높일 수 있지만 당장 현금을 늘리지 않음. 구형 GPU의 활용도와 중고가격, 임차 계약, 고객 집중, 관련 당사자의 자금 제공까지 확인해야 함. 대형 플랫폼과 외부 조달 의존도가 높은 AI 신생기업·네오클라우드를 같은 위험 등급으로 묶는 것은 적절하지 않음.''',('msq1','amznq3','googq3','metaq3'),table(['항목','볼 지표','경고 신호'],[['1 수익화','클라우드·AI 매출 성장 vs CAPEX','투자 증가에 비해 매출·사용량 회수가 지연됨'],['2 내부 자금','영업현금흐름·FCF·배당/매입 후 현금','여러 기간 지속되는 적자와 현금 감소'],['3 이자 지급','영업이익/이자비용','금리 상승·차입 증가에 따른 배율 하락'],['4 차입 구조','만기 분포·고정/변동·리스·보증','특정 연도 만기 집중·차환 의존'],['5 재무 여력','현금·순차입금·자기자본','현금 대비 단기 지급 부담 증가'],['6 자산 회수','가동률·감가상각·내용연수·GPU 잔존가치','유휴설비·수명 연장에 의존한 이익'],['7 고객의 현금','고객 집중·계약 해지권·투자 관계','공급자가 고객의 구매 자금까지 제공']]))

sec('03 AI 시대의 재무 이슈','rates','이슈 2. 유가·물가·금리의 재상승','고정금리 부채도 시간이 지나면 재조달 비용의 영향을 받음.', '''연준은 2026년 9월 16일 목표금리 범위를 25bp 인상해 3.75~4.00%로 조정했고, 10월 28일에는 이를 유지했음. 9월 의사록은 지정학적 에너지 가격 상승, 지속적인 물가 압력, 견조한 수요 등을 함께 다룸. ‘이란 전쟁 하나 때문에 금리가 올랐음’과 같은 단일 인과관계로 축약하지 않는 것이 적절함.

정책금리는 기업의 실제 차입금리와 같지 않음. 국채 수익률, 신용 스프레드, 만기, 담보, 통화, 리스 구조가 최종 자금비용을 결정함. 기존 고정금리 장기부채의 이자가 즉시 바뀌지는 않지만, 신규 투자와 만기 차환에는 새로운 금리가 반영됨. 투자 회수기간이 길수록 할인율 상승은 현재가치를 크게 낮출 수 있음.

1980년대의 교훈은 단순히 금리가 높은 나라가 진다는 것이 아님. 기술·수율·환율·고객 구조·정부 지원이 함께 작동했음. 현재 대형 빅테크는 기존 사업의 현금창출과 자본시장 접근성이 강하므로 당시의 취약한 메모리 기업과 동일시하기 어려움. 반면 회수 지연과 금리 상승이 겹치면 추가 투자 속도와 협력업체에 대한 지급 조건이 바뀔 수 있음.''',('fedsep','fedoct','fedminutes','volcker'),flow([('에너지 충격','전력·유가·운영비'),('물가 압력','금리 경로 변화'),('조달 비용','회사채·리스·차환'),('투자 판단','NPV·집행 시점 재평가')]))

sec('03 AI 시대의 재무 이슈','china','중국의 추격: 낮은 금리만으로 설명할 수 없음','모델 성능, 칩 자급, 총연산 능력은 서로 다른 비교축임.', '''중국이 상대적으로 낮은 금리와 정책금융, 전력·토지 지원을 활용하면 일부 프로젝트의 자본비용은 낮아질 수 있음. 다만 달러와 위안화의 명목금리를 직접 비교해 투자 경쟁력 차이로 환산하면 안 됨. 환율 위험, 자본 이동 제약, 보조금 조건, 신용 위험을 함께 반영해야 함. 미국 기업 역시 세액공제·지역 지원·장기 전력 계약을 활용할 수 있음.

Stanford의 2026 AI Index에 제시된 2026년 3월 Arena 비교에서는 미국 선두 모델 1,503점, 중국 선두 모델 1,464점으로 39점의 차이가 나타났음. 이는 특정 평가체계의 모델 성능 점수이며 경제적 생산성, 총 학습 연산량, 선단 반도체 제조 능력의 격차를 뜻하지 않음. Elo 계열 점수는 비율척도가 아니므로 점수 차이를 성능의 백분율 격차로 환산하면 안 됨.

경쟁은 여러 경로로 진행됨. 효율적인 모델과 추론 최적화는 동일한 연산으로 더 많은 서비스를 제공하게 해 줌. 반면 선단 GPU·HBM·제조장비에 대한 접근 제약은 확장 속도를 제한할 수 있음. 미국의 투자 둔화가 중국에 기회를 줄 수 있다는 것은 합리적인 시나리오이나, 저금리만으로 추월이 확정된다는 결론은 아님.''',('ai2026','fedsep'),table(['비교축','관측할 것','혼동하지 말 것'],[['모델 성능','동일 벤치마크·버전·날짜','칩 제조기술의 격차와 다름'],['경제성','추론 단가·전력효율·서비스 가격','최고 점수와 수익성은 다름'],['연산 규모','GPU·전력·네트워크 가용량','공장 발표 금액과 실제 가동량은 다름'],['자본비용','통화·보조금·신용·환헤지','국가별 기준금리 단순 비교는 부족함'],['공급 자립','설계·장비·소재·HBM·패키징','한 부문의 성과가 전체 자립을 뜻하지 않음']]))

sec('03 AI 시대의 재무 이슈','circular','이슈 3. 공급자·고객·투자자가 겹치는 거래','불법 여부보다 최종 수요가 만드는 외부 현금을 추적해야 함.', '''NVIDIA가 AI 기업에 투자하고 그 기업이 NVIDIA 시스템을 구매하거나, 클라우드 사업자가 AI 기업에 투자하고 그 기업이 클라우드 사용을 약정하면 자금과 매출의 경로가 서로 겹침. 이 구조는 고객의 자금조달을 도와 생태계를 키울 수 있음. 동시에 최종 서비스 매출이 부족한데도 투자자금으로 인프라 주문이 이어지는 것은 아닌지 확인할 필요가 생김.

2025년 9월 NVIDIA와 OpenAI는 최소 10GW의 시스템 배치와 단계적 투자 의향을 발표했음. 당시 최대 1,000억 달러라는 금액은 의향서에 담긴 상한이며, 전액 집행된 투자나 매출로 취급해서는 안 됨. 이후 거래의 규모·구조·집행 조건이 바뀔 수 있으므로 실제 주식 취득, 현금 송금, 장비 인도, 매출 인식은 개별 공시에서 따로 확인해야 함.

순환적인 관계가 있다고 자동으로 허위 매출이나 회계 부정이 되는 것은 아님. 독립적인 경제적 실체, 가격 조건, 현금 지급, 통제권 이전, 회수 가능성이 중요함. 투자와 구매 계약이 서로 조건부인지, 계약 취소 시 누가 손실을 부담하는지, 같은 자금을 여러 기업의 성장 지표로 중복 해석하고 있는지 살펴야 함.''',('nvoai','nvidia_annual'),flow([('칩 공급자·클라우드','지분 투자·신용 제공'),('AI 기업','서버 구매·컴퓨트 계약'),('공급자 매출','칩·서비스 대금'),('최종 고객','구독·사용료가 외부 현금의 원천')],'거래 구조의 개념도 · 특정 계약 전체가 이 방식으로 고정되었다는 의미가 아님'))

sec('03 AI 시대의 재무 이슈','vendor-finance','1990년대 통신장비의 벤더 파이낸싱과 비교','유사한 유동성 고리가 있어도 계약과 수요 구조는 다름.', '''통신망 구축 경쟁에서는 장비 공급자가 통신사업자의 구매를 대출·신용·지급 유예로 지원하는 벤더 파이낸싱이 활용되었음. 고객의 투자 예산이 부족해도 장비 판매를 늘릴 수 있었으나, 고객의 현금흐름이 기대에 못 미치면 장비 매출과 금융자산의 회수 위험이 동시에 악화되었음. 최종 통신 서비스 수요보다 투자와 조달이 앞선 부분이 취약점이었음.

현재 AI 투자와의 공통점은 공급자가 수요자의 확장을 자금 측면에서도 지원하고, 수요자의 미래 성장 기대가 현재 주문을 뒷받침한다는 점임. 차이는 대출·매출채권 중심의 금융지원과 지분투자·클라우드 계약·선급금이 혼합된 구조 사이에 있음. 기존 빅테크는 광고·소프트웨어·클라우드의 현금창출 기반도 보유하므로 신생 통신사업자와 동일한 재무상태가 아님.

유사 사례를 쓰는 목적은 붕괴 시점을 예언하는 데 있지 않음. 고객의 수익화가 지연될 때 공급자의 매출·채권·투자자산이 동시에 훼손되는 공통 충격을 찾는 데 있음. 최종 사용자 매출, 계약 이행, 투자자금 의존도, 고객 집중이 가장 중요한 관측 항목임.''',('nvoai','nvidia_annual'),table(['관점','통신장비 벤더 파이낸싱','AI 생태계 투자'],[['자금 형태','대출·지급 유예·매출채권','지분·대출·선급금·컴퓨트 약정의 혼합'],['판매 대상','통신장비·네트워크 구축','GPU·클라우드·데이터센터'],['핵심 위험','통신 고객 부도·대손','수익화 지연·투자 손실·고객 지급 위험'],['차이','신규 통신사와 과잉 네트워크','대형 플랫폼의 기존 현금창출과 AI 신생기업 공존'],['검증 기준','서비스 매출과 금융채권 회수','최종 사용료·독립적 수요·계약 이행']]))

sec('03 AI 시대의 재무 이슈','politics','이슈 4. 선거와 규제: 투자 장소와 시간을 바꾸는 힘','선거 결과와 법률의 시행은 별개의 단계임.', '''2026년 11월 4일 AP는 민주당의 상·하원 장악을 보도했음. 이 결과를 곧바로 전국 데이터센터 금지법의 시행으로 해석하면 안 됨. 새 의회는 2027년에 출범하며 법안 발의·통과·집행에는 별도의 과정이 필요함. 연방 정책 외에도 지방정부의 토지 이용, 전력망 접속, 물 사용, 소음, 전기요금 부담에 대한 결정이 실제 프로젝트에 영향을 줌.

지역 투표와 모라토리엄은 프로젝트의 비용·입지·가동 시점을 바꿀 수 있음. 반대가 증가한다는 사실과 투자 총량이 반드시 감소한다는 결론은 다름. 사업자는 다른 주나 국가로 이동하거나 자체 발전, 전력구매계약, 설계 변경으로 대응할 수 있음. 이때 이전 비용과 일정 지연은 자산의 수익률을 낮출 수 있음.

중국과의 기술 경쟁, 국가 안보, 지역 고용, 전력 안정성은 서로 충돌하는 정책 목표임. AI 투자를 완전히 중단하기 어렵다는 판단에는 이런 정치경제적 유인이 근거가 됨. 그러나 그 판단이 개별 프로젝트의 승인을 보장하지는 않음. 총량 전망과 특정 기업의 입지 위험을 분리해 관리해야 함.''',('election','dcvote','iea_ai'),table(['규제·병목','기업 재무에 미치는 경로','대응 비용'],[['전력망 접속','완공 후 가동 지연','자본화 이자·유휴설비·계약 위약금'],['전기요금 부담','운영비 증가','장기 전력구매·자가발전 투자'],['토지·물·소음','입지 승인 지연','설계 변경·다른 지역 이전'],['수출통제','판매 시장과 칩 공급 제한','제품 변경·공급망 재편'],['정치적 경쟁','지원과 규제가 동시 작동','보조금 조건·정책 불확실성']]))

sec('03 AI 시대의 재무 이슈','supplier','이슈 5. 공급자의 현금: 배당과 재투자의 균형','리니어의 질문이 훨씬 큰 규모로 다시 등장했음.', '''삼성전자의 2026년 설비투자 예상은 84.4조 원이며, 반도체 DS 부문 예상은 76.8조 원임. 2026년 총주주환원 예상 90조~110조 원은 확정·집행된 약 35조 원과 추가 예상 55조~75조 원을 포함하는 전망임. 최종 규모는 2027년 1월 이사회 결정 예정이므로 이미 전액 지급한 현금으로 표시하면 안 됨.

SK하이닉스는 2026년 3분기 말 현금 114.5조 원과 차입 15.8조 원으로 순현금 98.7조 원을 공시했음. 약 100조 원의 2026년 주주환원 계획과 용인 투자 확대도 제시했음. 순현금은 특정 시점의 잔액이고 환원은 일정 기간의 계획이므로 같은 종류의 숫자가 아님. 임직원 보상용 주식 매입은 주주환원 목적의 소각과 구분해야 함.

자본배분은 유지 투자, 성장 투자, 연구개발, 재무 안전판, 주주환원의 순서를 점검하는 문제임. 기술 전환과 공급 병목 해소를 위해 필요한 투자까지 줄이면 장기 경쟁력이 약해질 수 있음. 반대로 고점 수익을 근거로 경쟁력이 낮은 확장을 계속하면 다음 불황의 부담이 됨. 리니어의 장기 제품 수명과 낮은 투자 부담을 오늘의 HBM·선단공정에 그대로 적용할 수 없는 이유임.''',('samsungq3','samsungcapex','skq3','samsung_return'),table(['회사','확인된 숫자','해석'],[['삼성전자','2026 CAPEX 84.4조 원','회사 연간 예상'],['삼성전자','2026 환원 90–110조 원','확정·집행분 + 추가 예상, 최종 미확정'],['SK하이닉스','Q3 말 순현금 98.7조 원','현금 114.5 − 차입 15.8'],['SK하이닉스','2026 환원 약 100조 원','계획이며 현금 잔액과 다름'],['공통','용인·선단공정·HBM 투자','향후 투자 시점과 현금 유출 확인 필요']]))

sec('03 AI 시대의 재무 이슈','contracts','장기계약이 줄이는 위험과 남기는 위험','물량의 가시성과 현금 회수의 확실성은 같지 않음.', '''SK하이닉스는 14개 고객과의 장기계약이 2027~2028년 생산능력의 50% 이상을 포함한다고 설명했음. 합의한 가격 범위 안에서 시장 상황을 반영하는 메커니즘도 존재함. 따라서 계약이 있다는 사실만으로 미래 가격·마진·현금흐름이 고정되었다고 볼 수 없음. 계약의 기간, 물량, 최소 구매 의무, 가격 조정, 선급금, 해지 조항을 구체적으로 확인해야 함.

장기계약은 고객과 공급자의 계획을 맞추고 증설 위험을 일부 나눌 수 있음. 그러나 고객이 자금조달에 실패하거나 사업 규모를 줄이면 재협상과 지급 지연이 발생할 수 있음. 위약금 청구권이 있더라도 상대방이 지급할 수 있는지와 실제 회수 시점은 별개의 문제임. 고객을 잃는 비용 때문에 공급자가 계약상 권리를 전부 행사하지 못할 수도 있음.

이런 계약 구조가 2017년에는 전혀 없었다고 설명하는 것도 과도함. 반도체 산업에는 오래전부터 장기 공급계약·선급금·능력예약이 존재했음. AI 시대에는 고객 집중과 투자 규모, 공급 병목으로 그 중요성이 커졌다고 보는 편이 정확함. 호황기에 계약을 많이 확보할수록 최종 고객의 현금창출과 계약 집행 능력을 더 면밀하게 볼 필요 있음.''',('skq3','tsmc_annual'),table(['계약 요소','줄이는 불확실성','남는 위험'],[['최소 물량','생산계획·가동률','고객 지급 능력·해지·실제 집행'],['가격 범위','가격 변동 폭','범위 내 조정·믹스·원가 상승'],['선급금','초기 투자 재원','환급 조건·회계상 이연·고객 의존'],['위약금','취소 유인','소송·회수 가능성·관계 유지'],['장기 기간','판매 가시성','기술 전환·구형 제품 수요 감소']]))

sec('03 AI 시대의 재무 이슈','capital-framework','호황기의 자본배분을 평가하는 기준','가장 큰 지출보다 가장 오래 살아남는 현금 구조를 봐야 함.', '''투자안은 기대 매출 하나가 아니라 여러 수요·가격·가동률 시나리오로 평가해야 함. 정상 수요, 수익화 지연, 가격 하락, 금리 상승, 전력 접속 지연을 조합해도 유지 투자와 지급 의무를 감당할 수 있는지 확인해야 함. 모든 위험을 최악으로 합치는 방식보다는 서로 함께 발생할 가능성이 높은 위험을 묶는 것이 유용함.

현금 배분은 되돌리기 쉬운 결정과 어려운 결정을 구분해야 함. 공장 건설은 취소 비용이 높고 수년간 현금이 묶임. 자사주 매입은 조정이 쉬우나 고평가 매입은 손실을 남김. 배당은 반복 지급 기대를 형성함. 장기 R&D는 단기적으로 비용을 줄일 수 있어도 중단 후 재개하기 어려운 지식과 인력 손실이 있음.

따라서 현금이 많아졌다는 이유만으로 환원 확대나 투자 확대 중 하나를 정답으로 고를 수 없음. 자본비용을 넘는 투자 기회, 기술의 방어력, 투자와 만기의 배치, 고객의 현금창출, 정부 지원의 조건을 함께 검토해야 함. 과거 사례는 정답을 복사하는 자료가 아니라 현재의 취약한 고리를 찾는 비교 틀임.''',('linear_10k_2016','skq3','samsungq3'),flow([('경쟁력 유지','유지 CAPEX·핵심 R&D'),('가치 있는 성장','수익률 > 자본비용'),('불황 안전판','유동성·만기 분산'),('잔여 현금','배당·적정가격 자사주')],'자본배분 검토 순서의 예시 · 모든 회사에 고정된 우선순위는 아님'))

sec('03 AI 시대의 재무 이슈','recurrence','과거의 다섯 질문, 현재의 다섯 관측 항목','역사는 같은 사건이 아니라 비슷한 재무 구조로 반복됨.', '''AI 시대의 결말은 아직 정해져 있지 않음. 높은 산업 성장과 개별 투자 손실은 동시에 발생할 수 있으며, 수요가 조정되어도 기술의 장기 영향은 계속될 수 있음. 반도체 공급자의 호황만 보면 수요자의 조달 부담을 놓치고, 수요자의 CAPEX 부담만 보면 이미 존재하는 현금창출과 전략적 가치를 놓치게 됨.

리니어는 돈을 잘 버는 것과 독립적인 고성장을 이어가는 것이 다른 문제임을 보여 줌. 엘피다는 장기 자산의 가치와 상환일의 유동성이 다를 수 있음을 보여 줌. PC·인터넷·모바일의 변화는 수요의 중심을 맞히는 것만큼 투자 방식과 자금조달을 맞추는 일이 중요함을 보여 줌.

앞으로 점검할 것은 누가 가장 큰 숫자를 발표했는지가 아님. 매출이 현금으로 회수되는지, 투자한 자산이 사용되는지, 부채의 시간이 현금 회수의 시간과 맞는지, 다음 세대의 기술을 유지할 수 있는지임. 이 다섯 영역을 반복 관측하면 과거의 비유를 현재 기업의 구체적인 판단으로 바꿀 수 있음.''',('linear_defm14a','elpida_sec','wsts2026'),table(['영역','과거의 문제','현재의 관측 항목'],[['투자와 유동성','메모리 불황·엘피다의 차환 위험','빅테크 FCF·만기·AI 고객 지불 능력'],['자본비용','볼커 긴축·미일 제조 경쟁','국채·스프레드·전력비·정책금융'],['수요의 질','통신장비 벤더 파이낸싱','지분투자와 구매의 연결·최종 사용료'],['국가와 규제','군수 조달·무역 협정','전력·입지·보조금·미중 경쟁'],['자본배분','리니어의 배당·매각 선택','HBM/팹 투자·현금 안전판·주주환원']]))
glossary=[
('기초','반도체','조건에 따라 전류의 흐름을 조절할 수 있는 물질과 이를 이용한 소자를 통칭함. 실리콘이 대표적임. 전기를 단순히 잘 통하게 하는 금속과 달리 제어가 가능하다는 점이 핵심임.'),
('기초','트랜지스터','전기 신호를 증폭하거나 켜고 끄는 작은 소자임. 디지털 계산에서는 스위치, 아날로그 회로에서는 증폭기 역할로 이해하면 쉬움.'),
('기초','집적회로 · IC','여러 트랜지스터와 배선을 하나의 작은 기판 위에 함께 만든 회로임. 부품을 하나씩 연결하는 대신 한 번의 제조 흐름으로 묶어 만드는 방식임.'),
('기초','웨이퍼','칩을 여러 개 동시에 만드는 얇고 둥근 판임. 보통 실리콘으로 만듦. 빵을 여러 개 찍어내는 큰 반죽판으로 생각할 수 있음.'),
('기초','다이 · Die','웨이퍼에서 잘라낸 개별 회로 조각임. 다이에 보호 구조와 외부 연결을 붙여 패키지 형태로 완성함.'),
('기초','로직 반도체','계산·제어·판단을 수행하는 칩임. CPU·GPU 등이 여기에 속함. 데이터를 보관하는 메모리와 역할이 다름.'),
('기초','아날로그 반도체','현실의 연속적인 전압·소리·온도 등을 다루는 칩임. 전력관리, 신호 증폭, 디지털 변환 등에 쓰임.'),
('기초','혼합신호 · Mixed signal','아날로그와 디지털 기능을 같은 칩이나 시스템에서 함께 처리하는 구조임. 현실의 신호를 디지털 계산으로 연결하는 제품에서 중요함.'),
('기초','CPU','여러 종류의 작업을 유연하게 처리하는 중앙처리장치임. 다양한 업무를 조율하는 관리자에 비유할 수 있음.'),
('기초','GPU','많은 계산을 병렬로 처리하는 데 강한 장치임. 원래 그래픽 처리에서 발전했으며 AI의 행렬 연산에도 활용됨. 모든 작업에서 CPU보다 빠른 것은 아님.'),
('기초','AI 가속기 · ASIC','특정 계산을 효율적으로 수행하도록 설계한 칩임. ASIC은 주문형 반도체를 뜻하며 AI 이외의 용도로도 사용됨.'),
('기초','MCU','작은 컴퓨터의 핵심 기능을 한 칩에 묶은 마이크로컨트롤러임. 자동차·가전·산업기기의 제어에 많이 쓰임.'),
('기초','SoC','CPU·GPU·통신·제어 등의 기능을 한 칩에 통합한 시스템온칩임. 스마트폰의 핵심 칩이 대표 예시임.'),
('메모리','DRAM','전원이 공급되는 동안 작업 데이터를 보관하는 메모리임. 책상 위의 작업공간에 비유할 수 있음. 주기적으로 저장 정보를 갱신해야 함.'),
('메모리','NAND 플래시','전원이 꺼져도 데이터를 보관하는 메모리임. SSD·스마트폰 저장장치에 사용됨. 서랍이나 창고에 비유할 수 있음.'),
('메모리','HBM','DRAM을 여러 층으로 쌓고 넓은 연결 통로를 사용한 고대역폭 메모리임. GPU 가까이에서 많은 데이터를 빠르게 주고받도록 설계함.'),
('메모리','대역폭','일정 시간에 주고받을 수 있는 데이터의 양임. 도로의 차선 수와 비슷한 개념임. 데이터가 도착하는 데 걸리는 지연시간과 다름.'),
('메모리','지연시간 · Latency','요청한 뒤 첫 응답이 오기까지 걸리는 시간임. 차선이 넓어도 목적지가 멀면 오래 걸릴 수 있듯 대역폭과 별개임.'),
('메모리','SSD','NAND와 제어기를 이용한 저장장치임. NAND 가격만이 아니라 제어기·성능·내구성·인증이 제품 경쟁력을 결정함.'),
('메모리','비트 출하량','메모리 칩 개수 대신 저장 가능한 정보량으로 계산한 출하량임. 칩 하나의 용량이 커지면 칩 수가 같아도 비트 출하량은 늘어남.'),
('제조','팹 · Fab','웨이퍼에 반도체 회로를 만드는 공장임. 매우 청정한 환경과 고가 장비가 필요하며 완공 후에도 수율을 올리는 시간이 필요함.'),
('제조','공정 노드 · nm','제조기술 세대를 나타내는 명칭임. 숫자가 작을수록 대체로 선단 공정이지만 기업별 명칭을 실제 모든 부품의 물리적 길이와 동일시하면 안 됨.'),
('제조','노광','빛으로 회로 패턴을 웨이퍼에 옮기는 과정임. 사진을 찍듯 패턴을 전사하며 이후 식각·증착 등과 반복됨.'),
('제조','EUV','극자외선을 사용하는 노광 기술임. 더 미세한 패턴을 구현하기 위한 기술이며 고가 장비와 정교한 운영이 필요함.'),
('제조','식각 · Etching','필요 없는 물질을 선택적으로 제거하는 공정임. 만들어 놓은 패턴에 따라 재료를 깎아 회로 구조를 형성함.'),
('제조','증착 · Deposition','웨이퍼 표면에 얇은 물질 층을 입히는 공정임. 회로와 절연 구조를 여러 층으로 쌓는 데 사용함.'),
('제조','수율 · Yield','생산한 제품 중 정상 작동하는 제품의 비율임. 같은 공장과 투입비로 팔 수 있는 칩이 많아지므로 원가와 이익에 직접 영향을 줌.'),
('제조','가동률','보유 생산능력 중 실제 사용하는 비율임. 고정비가 큰 공장에서는 가동률이 떨어질수록 칩 한 개당 부담하는 비용이 커질 수 있음.'),
('제조','전공정·후공정','전공정은 웨이퍼에 회로를 형성하는 단계, 후공정은 잘라낸 칩을 패키징하고 테스트하는 단계임. 첨단 패키징에서는 후공정의 기술 중요성이 커지고 있음.'),
('제조','패키징','칩을 보호하고 전기적 연결과 열 배출 경로를 만드는 작업임. 단순 포장보다 복잡한 기능을 수행함.'),
('제조','첨단 패키징','여러 칩을 가깝게 연결해 성능과 전력효율을 높이는 고도화된 패키징임. 2.5D·3D 구조, 칩렛 통합 등이 포함됨.'),
('제조','TSV','실리콘을 수직으로 관통하는 연결 통로임. HBM처럼 칩을 쌓았을 때 층 사이 데이터를 전달하는 데 활용됨.'),
('제조','인터포저','칩 사이의 연결을 돕는 중간 기판임. GPU와 여러 HBM을 가까이 연결하는 구조에서 중요함.'),
('제조','칩렛','큰 칩을 기능별 작은 칩으로 나누어 연결하는 방식임. 수율과 설계 재사용에 유리할 수 있지만 연결·패키징 비용이 증가할 수 있음.'),
('사업 모델','팹리스','공장 없이 칩 설계와 판매에 집중하는 기업임. 제조 투자가 없다는 뜻이지 R&D·재고·선급금 부담까지 없다는 뜻은 아님.'),
('사업 모델','파운드리','다른 회사가 설계한 칩의 제조를 맡는 사업임. 공정기술·수율·생산 규모가 중요하며 높은 CAPEX를 부담함.'),
('사업 모델','IDM','칩 설계와 제조를 함께 수행하는 기업 모델임. 통합의 장점을 얻지만 설계와 공장 양쪽의 위험을 보유함.'),
('사업 모델','OSAT','외부 고객을 위한 반도체 패키징과 테스트 전문기업임. 제조한 칩을 실제 제품에 사용할 수 있도록 완성·검수하는 역할임.'),
('사업 모델','IP','여러 설계에서 재사용하는 검증된 설계 자산임. CPU 코어 같은 설계 블록을 사용료나 로열티 조건으로 제공함.'),
('사업 모델','EDA','전자회로 설계·배치·검증을 돕는 소프트웨어 도구임. 복잡한 칩의 오류를 줄이고 제조 가능한 설계를 만드는 데 필요함.'),
('사업 모델','Design win','고객 제품의 설계에 해당 칩이 채택되는 일임. 즉시 대량 매출이 발생한다는 뜻은 아니며 양산·판매 일정이 뒤따라야 함.'),
('사업 모델','테이프아웃','칩 설계를 제조 단계로 넘기는 중요한 이정표임. 이후 시제품 검증과 수율 확보가 필요하므로 완성품 매출과 같은 시점이 아님.'),
('AI 인프라','학습 · Training','많은 데이터를 이용해 모델의 내부 값을 조정하는 과정임. 대규모 연산과 메모리·통신 능력을 필요로 함.'),
('AI 인프라','추론 · Inference','학습된 모델로 실제 질문에 답하거나 결과를 생성하는 과정임. 사용자 수·응답 길이·모델 구조에 따라 필요한 자원이 달라짐.'),
('AI 인프라','하이퍼스케일러','대규모 클라우드와 데이터센터를 운영하는 사업자임. 막대한 내부 수요와 외부 고객 서비스를 함께 갖는 경우가 많음.'),
('AI 인프라','네오클라우드','주로 AI 연산에 특화된 신생 클라우드 사업자를 뜻하는 시장 용어임. 기존 광고·소프트웨어 현금창출이 큰 빅테크와 재무 구조가 다를 수 있음.'),
('AI 인프라','PUE','데이터센터 전체 전력 사용량을 IT 장비 전력 사용량으로 나눈 지표임. 1에 가까울수록 냉각 등 부대 전력의 비중이 작음.'),
('AI 인프라','GW·TWh','GW는 특정 순간의 전력 규모, TWh는 일정 기간 사용한 에너지량임. 발전소 용량과 연간 사용량을 같은 숫자로 비교하면 안 됨.'),
('재무','CAPEX','공장·장비·서버 등 장기간 사용하는 자산에 대한 투자임. 현금 지출은 먼저 발생하고 손익에는 감가상각으로 나뉘어 반영될 수 있음.'),
('재무','영업현금흐름 · OCF','본업에서 실제 유입·유출된 현금의 순액임. 순이익에 비현금 항목과 운전자본 변화를 반영하므로 순이익과 다를 수 있음.'),
('재무','FCF','통상 영업현금흐름에서 CAPEX를 뺀 현금흐름임. 기업마다 리스·자산처분·인센티브 처리 등이 다르므로 공시 정의를 확인해야 함.'),
('재무','운전자본','매출채권·재고·매입채무 등 영업 과정에서 묶이거나 확보되는 자금임. 매출이 늘어도 재고와 외상매출이 급증하면 현금은 줄 수 있음.'),
('재무','감가상각','장기자산 취득비를 사용기간에 나누어 비용으로 반영하는 회계 절차임. 해당 기간 감가상각비만큼 현금이 다시 나가는 것은 아님.'),
('재무','내용연수','자산을 경제적으로 사용할 것으로 보는 기간임. 연장하면 연간 감가상각이 줄 수 있지만 실제 자산 경쟁력과 현금회수가 개선되는 것은 아님.'),
('재무','WACC','부채와 자기자본의 자금조달비용을 비중에 따라 평균한 자본비용임. 사업 위험과 자본구조에 따라 다르므로 기준금리와 같지 않음.'),
('재무','NPV','미래 현금흐름을 할인해 현재가치로 바꾼 뒤 투자비를 차감한 값임. 할인율·성장률·투자 회수기간에 민감함.'),
('재무','만기 미스매치','투자한 자산의 현금회수보다 부채의 상환이 빨리 돌아오는 상태임. 가치 있는 공장을 보유해도 당장의 현금이 부족해질 수 있음.'),
('재무','차환 · Roll-over','만기가 도래한 부채를 새 자금으로 갚고 조달을 이어가는 일임. 시장이 막히거나 신용이 나빠지면 기존 계획이 어려워질 수 있음.'),
('재무','이자보상배율','통상 영업이익을 이자비용으로 나눈 값임. 이자로 지급해야 할 금액을 이익이 몇 배 덮는지 보여 줌. 원금 상환능력까지 보장하지는 않음.'),
('재무','부채비율','이 자료에서는 총부채/자기자본 ×100으로 정의함. 매입채무 등 무이자 영업 부채도 포함하며, 이자부 차입금 비율과 다름.'),
('재무','순현금·순차입금','현금성 자산과 이자부 차입금을 비교한 값임. 어떤 금융자산과 리스를 포함하는지에 따라 값이 달라질 수 있음.'),
('재무','DPS·배당성향','DPS는 주당배당, 배당성향은 이익 대비 배당 비율임. DPS 증가가 매출 증가나 배당의 지속 가능성을 자동으로 의미하지는 않음.'),
('재무','자사주 매입·소각','자기 회사 주식을 사는 것이 매입, 그 주식을 없애는 것이 소각임. 임직원 보상용 재교부와 영구 소각의 효과는 다름.'),
('재무','전환사채 · CB','일정 조건에서 주식으로 전환할 수 있는 채권임. 낮은 쿠폰의 대가로 미래 지분 희석 가능성이 생길 수 있음.'),
('재무','벤더 파이낸싱','판매자가 고객의 제품 구매 자금을 대출·지급 유예 등으로 지원하는 구조임. 판매 확대와 고객 신용위험이 연결됨.'),
('재무','LTA·Take-or-pay','LTA는 장기계약, Take-or-pay는 약정 물량을 받지 않아도 대금을 부담하는 계약 구조임. 모든 LTA가 Take-or-pay인 것은 아님.'),
('재무','TTM·FY·가이던스','TTM은 최근 12개월, FY는 회사 회계연도, 가이던스는 회사의 미래 예상임. 동일한 숫자 비교에서는 기간과 확정 여부를 먼저 맞춰야 함.'),
]
ghtml='<div class="glossary">'+''.join('<details class="term"><summary><span>'+E(cat)+'</span>'+E(term)+'</summary><p>'+E(desc)+'</p></details>' for cat,term,desc in glossary)+'</div>'
sec('04 용어와 기록','glossary','입문자를 위한 반도체·기업재무 용어','비슷한 용어를 구분하면 산업 기사와 공시가 더 쉽게 읽힘.', '''용어는 기술 자체의 정의와 재무적으로 중요한 의미를 함께 정리함. 비유는 이해를 돕기 위한 것이며 실제 공정이나 계약의 모든 예외를 포함하지 않음. 회사별 제품과 사업 범위는 변할 수 있으므로 대표 기업 목록은 해당 역할을 이해하기 위한 예시로 사용함.''',('foundry_model','hbm_definition','micron_memory'),ghtml)

methodtable=table(['구분','자료 처리 원칙'],[['실적','공시·공식 통계의 해당 기간 수치를 사용함. 연간·분기·TTM을 표기함.'],['전망','회사 가이던스·기관 전망은 실제 지출이나 확정 실적과 구분함.'],['계산','CAGR·FCF·비율은 산식과 단위를 공개함.'],['비교','연결범위·인수·회계연도·총액/순액 정의 차이를 확인함.'],['해석','원인·전망·역사적 유추는 관측 사실과 구분함.'],['이미지','역사 사진은 출처·저작자·라이선스를 함께 표기함. 복제품은 구분함.']])
sec('04 용어와 기록','method','자료의 범위와 읽는 기준','조사 기준일 2026.11.08 · 미래 수치는 전망으로 분리함.', '''리니어의 과거 재무는 기존 보관된 10-K·SEC XBRL 자료에서 가져왔음. FY2008 순이익 등 과거 재표시가 있는 항목은 보고 버전에 따라 달라질 수 있으며, 여기서는 매출·DPS 추이를 중심으로 사용함. 빅테크 시계열은 SEC XBRL과 실적 발표의 원자료를 이용했으며, FCF는 비교를 위해 동일한 총현금 CAPEX 기준으로 계산함.

금융·산업 통계에는 명목 달러와 환율의 영향이 있음. 반도체 매출 증가가 실물 생산량 증가와 같지 않고, 기업 순위는 집계 범위에 따라 달라짐. 사진과 개념도는 수치의 증거를 대신하지 않음. 개념도는 가능한 관계를 설명하고, 수치 그래프는 출처에 있는 관측값을 보여 주는 용도로 구분함.

자료는 산업사와 재무 구조를 함께 보관하는 학습 기록임. 현재의 호황이나 경쟁구도를 영구적인 상태로 가정하지 않음. 새로운 실적·계약·규제가 나오면 기간과 정의를 맞춰 갱신하는 방식이 적절함.''',('linear_10k_2016','WSTS','msq1','amznq3'),methodtable)

