attrs=json.loads((P/'assets/v3/attribution.json').read_text(encoding='utf-8'))
def photo(a):
 f=P/a['path']; mime='image/png' if f.suffix=='.png' else 'image/jpeg'; uri='data:'+mime+';base64,'+base64.b64encode(f.read_bytes()).decode()
 return '<figure class="photo"><img loading="lazy" src="'+uri+'" alt="'+E(a['caption'])+'"><figcaption><b>'+E(a['caption'])+'</b><br><a href="'+a['source']+'" target="_blank" rel="noopener">'+E(a['credit'])+'</a> · <a href="'+a['licenseUrl']+'" target="_blank" rel="noopener">'+E(a['license'])+'</a> · 원본 비율 유지, 추가 변경 없음</figcaption></figure>'
attach={'origin-invention':['transistor','ic-replica'],'origin-state':['apollo11'],'pc-us-japan':['ibm-pc']}
for s in sections:
 if s['id'] in attach:s['body']='<div class="photos">'+''.join(photo(a) for a in attrs if a['id'] in attach[s['id']])+'</div>'+s['body']
if (P/'macro_raw.json').exists():
 m=json.loads((P/'macro_raw.json').read_text(encoding='utf-8'))
 yrs=list(range(1978,1993)); rate=[]
 for yr in yrs:
  values=[v for d,v in m['FEDFUNDS'] if d.startswith(str(yr)) and v is not None];rate.append(round(sum(values)/len(values),2) if values else None)
 for s in sections:
  if s['id']=='pc-us-japan':s['body']+=linechart('볼커 긴축 전후의 미국 금리',[str(y) for y in yrs],[('연방기금 유효금리 연평균',rate,'#ffb15e')],'% · 월별 자료의 산술평균')+'<p class="chartnote">FRED FEDFUNDS. 정책 목표범위가 아닌 유효금리이며 월평균의 연평균임. 1981년 중반 약 19%라는 월별 수치와 연평균은 다름.</p>';s['refs']=tuple(list(s['refs'])+['fred'])

