for group in groups:
 toc+='<div class="navgroup"><h3>'+E(group)+'</h3>'+''.join('<a href="#'+s['id']+'" data-id="'+s['id']+'">'+E(s['title'])+'</a>' for s in sections if s['group']==group)+'</div>'
body=''; used=set()
for group in groups:
 body+='<div class="group" data-group="'+group+'">'+group+'</div>'
 for s in [s for s in sections if s['group']==group]:
  idx=sections.index(s)+1
  refs=[k for k in s['refs'] if k in sources]; used.update(refs)
  sourcehtml='<details class="sources"><summary>근거 자료 '+str(len(refs))+'건</summary><ul>'+''.join('<li><a href="'+sources[k][1]+'" target="_blank" rel="noopener">'+E(sources[k][0])+'</a></li>' for k in refs)+'</ul></details>'
  body+='<section class="section" id="'+s['id']+'" data-group="'+group+'"><div class="idx">ARCHIVE / '+str(idx).zfill(2)+'</div><h2>'+s['title']+'</h2><div class="lead">'+s['lead']+'</div>'+s['body']+sourcehtml+'</section>'
